    Position: Comp({ x: I(0), y: I(0), z: I(0) }),
    Size: Comp({ x: I(W), y: I(H), z: I(L) }),
    BlockStatePalette: List(10, palItems),
    BlockStates: LongArr(pack(idx, bits)),
    Entities: List(10, []),
    TileEntities: List(10, []),
    PendingBlockTicks: List(10, []),
    PendingFluidTicks: List(10, [])
